import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import styled from 'styled-components';

const EmployeePage = () => {
  const { registrationNumber } = useParams(); // Lorry registration number
  const { id } = useParams(); // Lorry ID from the route
  const [employeeName, setEmployeeName] = useState('');
  const [employeePhone, setEmployeePhone] = useState('');
  const [employeeRole, setEmployeeRole] = useState('driver'); // Default role
  const [employeeSalary, setEmployeeSalary] = useState('');
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [selectedEmployee, setSelectedEmployee] = useState(null); // For employee details

  // Add new employee
  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
        lorry_id: id, // Use ID directly
      };
      const response = await axios.post('http://localhost:5001/api/employee/add', newEmployee);
      fetchEmployeesByRole(employeeRole); // Refresh employee list after adding
    } catch (error) {
      console.error('Error adding employee:', error);
    }
  };

  // Fetch employees by role
  const fetchEmployeesByRole = async (role) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/employee/employeesByRole/${id}/${role}`);
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error('Error fetching employees:', error);
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole); // Fetch employees of the default role on load
  }, [employeeRole]);

  // Handle role change to fetch filtered employees
  const handleRoleChange = (e) => {
    const selectedRole = e.target.value;
    setEmployeeRole(selectedRole);
    fetchEmployeesByRole(selectedRole); // Fetch employees of selected role
  };

  // Handle employee selection
  const handleEmployeeClick = async (phone) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/employee/findByPhone/${phone}`);
      setSelectedEmployee(response.data[0]); // Set selected employee's details
    } catch (error) {
      console.error('Error fetching employee details:', error);
    }
  };

  // Handle delete employee
  const handleDeleteEmployee = async (phone) => {
    try {
      const response = await axios.delete(`http://localhost:5001/api/employee/delete/${phone}`);
      alert('Employee deleted successfully');
      fetchEmployeesByRole(employeeRole); // Refresh employee list
    } catch (error) {
      console.error('Error deleting employee:', error);
    }
  };

  return (
    <Container>
      <Header>
        <LorryTitle>{registrationNumber}</LorryTitle>
        <OwnerInfo>
          <div>Owner: John Doe</div>
          <div>Phone: +123456789</div>
        </OwnerInfo>
        <ManagerInfo>Manager: Jane Doe</ManagerInfo>
      </Header>

      {/* Add Employee Form */}
      <Form>
        <FormTitle>Add New Employee</FormTitle>
        <Input
          type="text"
          placeholder="Employee Name"
          value={employeeName}
          onChange={(e) => setEmployeeName(e.target.value)}
        />
        <Input
          type="text"
          placeholder="Phone Number"
          value={employeePhone}
          onChange={(e) => setEmployeePhone(e.target.value)}
        />
        <Select value={employeeRole} onChange={handleRoleChange}>
          <option value="driver">Driver</option>
          <option value="driller">Driller</option>
          <option value="manager">Lorry Manager</option>
          <option value="worker">Worker</option>
        </Select>
        <Input
          type="number"
          placeholder="Fixed Salary"
          value={employeeSalary}
          onChange={(e) => setEmployeeSalary(e.target.value)}
        />
        <Button onClick={addEmployee}>Add Employee</Button>
      </Form>

      {/* Display Employees by Role */}
      <EmployeeRoles>
        <RoleTabs>
          <Tab onClick={() => setEmployeeRole('driver')}>Drivers</Tab>
          <Tab onClick={() => setEmployeeRole('driller')}>Drillers</Tab>
          <Tab onClick={() => setEmployeeRole('manager')}>Managers</Tab>
          <Tab onClick={() => setEmployeeRole('worker')}>Workers</Tab>
        </RoleTabs>

        <EmployeeList>
          {filteredEmployees.map((employee) => (
            <EmployeeItem key={employee.phone} onClick={() => handleEmployeeClick(employee.phone)}>
              {employee.name} ({employee.phone})
            </EmployeeItem>
          ))}
        </EmployeeList>
      </EmployeeRoles>

      {/* Employee Details Modal */}
      {selectedEmployee && (
        <EmployeeDetails>
          <h3>{selectedEmployee.name} ({selectedEmployee.phone})</h3>
          <p><strong>Fixed Salary:</strong> {selectedEmployee.fixed_salary}</p>
          <p><strong>Expense:</strong> {/* Show expense */}</p>
          <p><strong>Earned Money:</strong> {/* Show earned money */}</p>
          <p><strong>Remaining Amount:</strong> {/* Show remaining amount */}</p>
          <p><strong>Days Worked:</strong> {/* Show days worked */}</p>

          <Button onClick={() => handleDeleteEmployee(selectedEmployee.phone)}>Delete Employee</Button>
        </EmployeeDetails>
      )}
    </Container>
  );
};

// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
  font-family: Arial, sans-serif;
`;

const Header = styled.header`
  display: flex;
  justify-content: space-between;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  align-items: center;
`;

const LorryTitle = styled.h1`
  font-size: 1.5rem;
  font-weight: bold;
`;

const OwnerInfo = styled.div`
  text-align: center;
  font-size: 1rem;
`;

const ManagerInfo = styled.div`
  text-align: right;
  font-size: 1rem;
  font-weight: bold;
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const FormTitle = styled.h2`
  margin-bottom: 15px;
  font-size: 1.3rem;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Button = styled.button`
  width: 100%;
  padding: 12px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s ease;

  &:hover {
    background-color: #45a049;
  }
`;

const EmployeeRoles = styled.div`
  margin-top: 30px;
`;

const RoleTabs = styled.div`
  display: flex;
  justify-content: space-around;
  margin-bottom: 20px;
`;

const Tab = styled.div`
  cursor: pointer;
  font-size: 1.1rem;
  padding: 10px 20px;
  background-color: #f4f7fc;
  border-radius: 5px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #e1e7f2;
  }
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  padding: 10px;
  border-bottom: 1px solid #ccc;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const EmployeeDetails = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

export default EmployeePage;
